    "ans": 1,
    "sol": "<p>\\(v=3t^2-12t+9=3(t-1)(t-3)\\), which is zero at 1 s and 3 s. t = 2 s is where acceleration \\(6t-12\\) is zero. At t = 0 the velocity is 9 m/s, not zero.</p>"
