    "ans": 0,
    "sol": "<p>\\(\\sqrt{3^2+4^2}=5\\). 7 adds the two maxima, but \\(\\sin\\theta\\) and \\(\\cos\\theta\\) cannot both be 1 at the same angle. 1 is the difference; 12 is the product.</p>"
